"use client";

import { useState, useEffect, use } from "react";
import { api } from "@/lib/axios";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

export default function EditProductPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const router = useRouter();
  const { id } = use(params);
  const [categories, setCategories] = useState([]);
  const [serviceTypes, setServiceTypes] = useState([]);
  const [loading, setLoading] = useState(true);

  const [formData, setFormData] = useState({
    productCode: "",
    productName: "",
    brand: "",
    modelNumber: "",
    categoryId: "",
    serviceTypeId: "",
    unit: "pcs",

    shortDescription: "",
    detailedDescription: "",
    technicalSpecification: "",

    costPrice: "",
    sellingPrice: "",
    minimumSellingPrice: "",
    currency: "KWD",
    taxable: true,
    taxRate: 0,

    warrantyPeriod: "",
    productImage: "",
    datasheetAttachment: "",
    installationNotes: "",
    internalNotes: "",
    isActive: true,
  });

  useEffect(() => {
    Promise.all([
      api.get("/catalog/categories"),
      api.get("/catalog/service-types"),
      api.get(`/catalog/products/${id}`),
    ])
      .then(([catRes, srvRes, prodRes]) => {
        setCategories(catRes.data);
        setServiceTypes(srvRes.data);
        const p = prodRes.data;
        setFormData({
          productCode: p.productCode || "",
          productName: p.productName || "",
          brand: p.brand || "",
          modelNumber: p.modelNumber || "",
          categoryId: p.categoryId || "",
          serviceTypeId: p.serviceTypeId || "",
          unit: p.unit || "pcs",

          shortDescription: p.shortDescription || "",
          detailedDescription: p.detailedDescription || "",
          technicalSpecification: p.technicalSpecification || "",

          costPrice: p.costPrice?.toString() || "0",
          sellingPrice: p.sellingPrice?.toString() || "0",
          minimumSellingPrice: p.minimumSellingPrice?.toString() || "0",
          currency: p.currency || "KWD",
          taxable: p.taxable ?? true,
          taxRate: p.taxRate || 0,

          warrantyPeriod: p.warrantyPeriod || "",
          productImage: p.productImage || "",
          datasheetAttachment: p.datasheetAttachment || "",
          installationNotes: p.installationNotes || "",
          internalNotes: p.internalNotes || "",
          isActive: p.isActive ?? true,
        });
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        alert("Failed to load product data.");
        router.push("/dashboard/catalog/products");
      });
  }, [id, router]);

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    try {
      const payload = {
        ...formData,
        costPrice: parseFloat(formData.costPrice || "0"),
        sellingPrice: parseFloat(formData.sellingPrice || "0"),
        minimumSellingPrice: parseFloat(formData.minimumSellingPrice || "0"),
        taxRate: parseFloat((formData.taxRate as any) || "0"),
      };
      await api.patch(`/catalog/products/${id}`, payload);
      alert("Product updated successfully!");
      router.push("/dashboard/catalog/products");
    } catch (error: any) {
      alert(error.response?.data?.message || "Error updating product");
    }
  };

  const handleDelete = async () => {
    if (!confirm("Are you sure you want to permanently delete this product?"))
      return;
    try {
      await api.delete(`/catalog/products/${id}`);
      router.push("/dashboard/catalog/products");
    } catch (e: any) {
      alert("Cannot delete product. It may be used in an existing quotation.");
    }
  };

  if (loading) return <div className="p-8 text-center">Loading product...</div>;

  return (
    <div className="max-w-4xl mx-auto space-y-6 pb-12">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Edit Product</h1>
          <p className="text-gray-500 mt-1">
            {formData.productCode} - {formData.productName}
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            variant="outline"
            className="text-red-600 border-red-200 hover:bg-red-50"
            onClick={handleDelete}
          >
            Delete
          </Button>
          <Button variant="outline" onClick={() => router.back()}>
            Cancel
          </Button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="space-y-6">
        {/* Basic Information */}
        <Card>
          <CardHeader>
            <CardTitle>Basic Information</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>
                  Product Code <span className="text-red-500">*</span>
                </Label>
                <Input
                  required
                  value={formData.productCode}
                  onChange={(e) =>
                    setFormData({ ...formData, productCode: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>
                  Product Name <span className="text-red-500">*</span>
                </Label>
                <Input
                  required
                  value={formData.productName}
                  onChange={(e) =>
                    setFormData({ ...formData, productName: e.target.value })
                  }
                />
              </div>

              <div className="space-y-2">
                <Label>
                  Service Type <span className="text-red-500">*</span>
                </Label>
                <select
                  required
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formData.serviceTypeId}
                  onChange={(e) =>
                    setFormData({ ...formData, serviceTypeId: e.target.value })
                  }
                >
                  <option value="">Select...</option>
                  {serviceTypes.map((s: any) => (
                    <option key={s.id} value={s.id}>
                      {s.name}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>
                  Category <span className="text-red-500">*</span>
                </Label>
                <select
                  required
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formData.categoryId}
                  onChange={(e) =>
                    setFormData({ ...formData, categoryId: e.target.value })
                  }
                >
                  <option value="">Select...</option>
                  {categories.map((c: any) => (
                    <option key={c.id} value={c.id}>
                      {c.name}
                    </option>
                  ))}
                </select>
              </div>

              <div className="space-y-2">
                <Label>Brand</Label>
                <Input
                  value={formData.brand}
                  onChange={(e) =>
                    setFormData({ ...formData, brand: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Model Number</Label>
                <Input
                  value={formData.modelNumber}
                  onChange={(e) =>
                    setFormData({ ...formData, modelNumber: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Unit of Measure</Label>
                <Input
                  value={formData.unit}
                  onChange={(e) =>
                    setFormData({ ...formData, unit: e.target.value })
                  }
                  placeholder="pcs, m, kg..."
                />
              </div>
              <div className="space-y-2 flex items-center pt-8">
                <input
                  type="checkbox"
                  id="isActive"
                  checked={formData.isActive}
                  onChange={(e) =>
                    setFormData({ ...formData, isActive: e.target.checked })
                  }
                  className="mr-2"
                />
                <Label htmlFor="isActive">Product is Active</Label>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Pricing & Tax */}
        <Card>
          <CardHeader>
            <CardTitle>Pricing & Tax</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>
                  Cost Price <span className="text-red-500">*</span>
                </Label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={formData.costPrice}
                  onChange={(e) =>
                    setFormData({ ...formData, costPrice: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>
                  Selling Price <span className="text-red-500">*</span>
                </Label>
                <Input
                  type="number"
                  step="0.01"
                  required
                  value={formData.sellingPrice}
                  onChange={(e) =>
                    setFormData({ ...formData, sellingPrice: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Minimum Selling Price</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={formData.minimumSellingPrice}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      minimumSellingPrice: e.target.value,
                    })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Currency</Label>
                <Input
                  value={formData.currency}
                  onChange={(e) =>
                    setFormData({ ...formData, currency: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2 flex items-center pt-8">
                <input
                  type="checkbox"
                  id="taxable"
                  checked={formData.taxable}
                  onChange={(e) =>
                    setFormData({ ...formData, taxable: e.target.checked })
                  }
                  className="mr-2"
                />
                <Label htmlFor="taxable">Is Taxable?</Label>
              </div>
              {formData.taxable && (
                <div className="space-y-2">
                  <Label>Tax Rate (%)</Label>
                  <Input
                    type="number"
                    step="0.1"
                    value={formData.taxRate}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        taxRate: parseFloat(e.target.value) || 0,
                      })
                    }
                  />
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Descriptions & Specs */}
        <Card>
          <CardHeader>
            <CardTitle>Descriptions & Technical</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              <div className="space-y-2">
                <Label>Short Description (Used in Quotes)</Label>
                <Input
                  value={formData.shortDescription}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      shortDescription: e.target.value,
                    })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Detailed Description</Label>
                <Textarea
                  className="h-24"
                  value={formData.detailedDescription}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      detailedDescription: e.target.value,
                    })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Technical Specification</Label>
                <Textarea
                  className="h-24 font-mono text-sm"
                  placeholder="Key: Value&#10;Key: Value"
                  value={formData.technicalSpecification}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      technicalSpecification: e.target.value,
                    })
                  }
                />
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Media & Notes */}
        <Card>
          <CardHeader>
            <CardTitle>Media & Notes</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2 col-span-2">
                <Label>Product Image</Label>
                <div className="flex gap-4 items-center">
                  {formData.productImage && (
                    <img
                      src={formData.productImage}
                      alt="Preview"
                      className="w-16 h-16 object-cover rounded-md border"
                    />
                  )}
                  <Input
                    type="file"
                    accept="image/*"
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (!file) return;
                      const reader = new FileReader();
                      reader.onloadend = () => {
                        setFormData({
                          ...formData,
                          productImage: reader.result as string,
                        });
                      };
                      reader.readAsDataURL(file);
                    }}
                  />
                  {formData.productImage && (
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() =>
                        setFormData({ ...formData, productImage: "" })
                      }
                    >
                      Clear
                    </Button>
                  )}
                </div>
              </div>
              <div className="space-y-2">
                <Label>Datasheet URL</Label>
                <Input
                  value={formData.datasheetAttachment}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      datasheetAttachment: e.target.value,
                    })
                  }
                  placeholder="https://..."
                />
              </div>
              <div className="space-y-2">
                <Label>Warranty Period</Label>
                <Input
                  value={formData.warrantyPeriod}
                  onChange={(e) =>
                    setFormData({ ...formData, warrantyPeriod: e.target.value })
                  }
                  placeholder="e.g. 1 Year"
                />
              </div>
              <div className="space-y-2 col-span-2">
                <Label>Installation Notes</Label>
                <Textarea
                  value={formData.installationNotes}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      installationNotes: e.target.value,
                    })
                  }
                />
              </div>
              <div className="space-y-2 col-span-2">
                <Label>Internal Notes (Not shown to customers)</Label>
                <Textarea
                  className="bg-yellow-50"
                  value={formData.internalNotes}
                  onChange={(e) =>
                    setFormData({ ...formData, internalNotes: e.target.value })
                  }
                />
              </div>
            </div>
          </CardContent>
        </Card>

        <div className="flex justify-end gap-3">
          <Button type="button" variant="outline" onClick={() => router.back()}>
            Cancel
          </Button>
          <Button type="submit" className="bg-blue-600 hover:bg-blue-700">
            Save Changes
          </Button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { api } from "@/lib/axios";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Plus, Search } from "lucide-react";
import { useRouter } from "next/navigation";
import { Badge } from "@/components/ui/badge";

export default function CatalogProductsPage() {
  const [products, setProducts] = useState([]);
  const [search, setSearch] = useState("");
  const router = useRouter();

  async function fetchProducts() {
    try {
      const { data } = await api.get("/catalog/products");
      setProducts(data);
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    fetchProducts();
  }, []);


  const filtered = products.filter(
    (p: any) =>
      p.productName.toLowerCase().includes(search.toLowerCase()) ||
      p.productCode.toLowerCase().includes(search.toLowerCase()),
  );

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">Product Catalog</h1>
        <Button onClick={() => router.push("/dashboard/catalog/products/new")}>
          <Plus className="w-4 h-4 mr-2" /> Add Product
        </Button>
      </div>

      <Card>
        <CardHeader className="py-4">
          <div className="relative w-full md:w-96">
            <Search className="absolute left-3 top-3 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Search products by name or code..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>
        </CardHeader>
        <CardContent className="p-0">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-gray-500 font-semibold border-b">
              <tr>
                <th className="px-6 py-3 w-16">Image</th>
                <th className="px-6 py-3">Code</th>
                <th className="px-6 py-3">Product Name</th>
                <th className="px-6 py-3">Brand</th>
                <th className="px-6 py-3">Category</th>
                <th className="px-6 py-3">Price</th>
                <th className="px-6 py-3">Unit</th>
                <th className="px-6 py-3">Status</th>
              </tr>
            </thead>
            <tbody>
              {filtered.map((p: any) => (
                <tr
                  key={p.id}
                  className="border-b hover:bg-gray-50 cursor-pointer"
                  onClick={() =>
                    router.push(`/dashboard/catalog/products/${p.id}`)
                  }
                >
                  <td className="px-6 py-4">
                    {p.productImage ? (
                      <img
                        src={p.productImage}
                        alt={p.productName}
                        className="w-10 h-10 object-cover rounded-md border bg-white"
                      />
                    ) : (
                      <div className="w-10 h-10 bg-gray-100 rounded-md border flex items-center justify-center text-gray-400 text-xs">
                        No Img
                      </div>
                    )}
                  </td>
                  <td className="px-6 py-4 font-medium text-blue-600">
                    {p.productCode}
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-medium text-gray-900">
                      {p.productName}
                    </div>
                    <div
                      className="text-xs text-gray-500 mt-1 max-w-[200px] truncate"
                      title={p.shortDescription}
                    >
                      {p.shortDescription || "No description"}
                    </div>
                  </td>
                  <td className="px-6 py-4">{p.brand || "-"}</td>
                  <td className="px-6 py-4 text-gray-500">
                    {p.category?.name || "-"}
                  </td>
                  <td className="px-6 py-4 font-semibold">
                    {p.sellingPrice} KWD
                  </td>
                  <td className="px-6 py-4 text-gray-500">{p.unit}</td>
                  <td className="px-6 py-4">
                    <Badge variant={p.isActive ? "default" : "secondary"}>
                      {p.isActive ? "ACTIVE" : "INACTIVE"}
                    </Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          {filtered.length === 0 && (
            <div className="text-center py-10 text-gray-500">
              No products found.
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { api } from "@/lib/axios";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export default function NewCustomerPage() {
  const router = useRouter();
  const [formData, setFormData] = useState({
    displayName: "",
    customerType: "COMPANY",
    email: "",
    phone: "",
    status: "ACTIVE",
  });

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    try {
      const { data } = await api.post("/customers", formData);
      router.push(`/dashboard/customers/${data.id}`);
    } catch (error) {
      alert("Error creating customer");
    }
  };

  return (
    <div className="max-w-2xl mx-auto space-y-6">
      <h1 className="text-3xl font-bold">New Customer</h1>
      <Card>
        <CardHeader>
          <CardTitle>Customer Details</CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="space-y-2">
              <Label>Display Name</Label>
              <Input
                required
                value={formData.displayName}
                onChange={(e) =>
                  setFormData({ ...formData, displayName: e.target.value })
                }
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Type</Label>
                <select
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formData.customerType}
                  onChange={(e) =>
                    setFormData({ ...formData, customerType: e.target.value })
                  }
                >
                  <option value="COMPANY">Company</option>
                  <option value="INDIVIDUAL">Individual</option>
                  <option value="GOVERNMENT">Government</option>
                </select>
              </div>
              <div className="space-y-2">
                <Label>Email</Label>
                <Input
                  type="email"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Phone</Label>
                <Input
                  value={formData.phone}
                  onChange={(e) =>
                    setFormData({ ...formData, phone: e.target.value })
                  }
                />
              </div>
            </div>
            <div className="flex justify-end space-x-2 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.back()}
              >
                Cancel
              </Button>
              <Button type="submit">Save Customer</Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState, use } from "react";
import { api } from "@/lib/axios";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import {
  Download,
  ArrowLeft,
  Send,
  Play,
  CheckCircle,
  CreditCard,
  History,
  FileText,
  Trash2,
} from "lucide-react";
import { useRouter } from "next/navigation";

export default function InvoiceDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const [invoice, setInvoice] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("details");
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);

  const [paymentForm, setPaymentForm] = useState({
    amount: 0,
    paymentMethod: "BANK_TRANSFER",
    referenceNumber: "",
    notes: "",
  });

  const router = useRouter();

  async function fetchInvoice() {
    try {
      const { data } = await api.get(`/invoices/${id}`);
      setInvoice(data);
      setPaymentForm((prev) => ({ ...prev, amount: data.balanceAmount }));
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchInvoice();
  }, [id]);


  async function handleAction(action: string) {
    try {
      if (action === "issue") {
        await api.post(`/invoices/${id}/issue`);
        alert("Invoice Issued!");
      }
      fetchInvoice();
    } catch (e) {
      console.error(e);
      alert("Action failed.");
    }
  };

  async function handleRecordPayment() {
    try {
      await api.post(`/invoices/${id}/payments`, paymentForm);
      alert("Payment recorded successfully!");
      setShowPaymentModal(false);
      fetchInvoice();
    } catch (e) {
      console.error(e);
      alert("Failed to record payment. Check amount.");
    }
  };

  async function generatePdf() {
    setIsGenerating(true);
    try {
      const response = await api.post(`/invoices/${id}/generate-pdf`, {}, {
        responseType: "blob",
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `${invoice.invoiceNumber || "invoice"}.pdf`,
      );
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
    } catch (e) {
      console.error(e);
      alert("Failed to generate PDF");
    } finally {
      setIsGenerating(false);
    }
  };

  if (loading) return <div className="p-8">Loading invoice details...</div>;
