// ── Status pill ──────────────────────────────────────────────────────────────
const STATUS_CLASS: Record<string, string> = {
  DRAFT: "status-draft",
  PENDING_REVIEW: "status-pending",
  PENDING_APPROVAL: "status-pending",
  APPROVED: "status-approved",
  REJECTED: "status-rejected",
  CONVERTED_TO_INVOICE: "status-converted",
