              </table>
            </div>
          </div>
        );
      case 3:
        return (
          <div className="space-y-4">
            <div className="flex justify-between items-center mb-4">
              <h3 className="text-xl font-semibold">Scope & Terms</h3>
            </div>

            <div className="mb-6">
              <label className="block text-sm font-medium mb-1">
                Scope of Work Summary <span className="text-red-500">*</span>
              </label>
              <ReactQuill
                theme="snow"
                modules={quillModules}
                formats={quillFormats}
                value={formData.scopeSummary || ""}
                onChange={(val) => updateForm("scopeSummary", val)}
                className="bg-white mt-1"
                placeholder="Briefly describe the overall scope of this project..."
              />
              <p className="text-xs text-gray-500 mt-1">
                This summary is required before the quotation can be approved.
              </p>
            </div>
            <p className="text-sm text-gray-500 mb-4">
              Add specific terms for this quotation. Any terms you leave blank
              here will be auto-populated by the system if the selected Service
              Type has defaults.
            </p>

            <div className="flex gap-2 mb-4 bg-gray-50 p-4 border rounded-lg">
              <select
                className="border rounded-md p-2 bg-white flex-1"
                id="template-select"
              >
                <option value="">-- Add from Template --</option>
                {termsTemplates.map((t: any) => (
                  <option key={t.id} value={t.id}>
                    {t.title} ({t.category?.name || "Uncategorized"})
                  </option>
                ))}
              </select>
              <Button
                variant="secondary"
                onClick={() => {
                  const select = document.getElementById(
                    "template-select",
                  ) as HTMLSelectElement;
                  const tmplId = select.value;
                  if (!tmplId) return;
                  const tmpl = termsTemplates.find((t: any) => t.id === tmplId);
                  if (tmpl) {
                    updateForm("terms", [
                      ...formData.terms,
                      { content: tmpl.content, categoryId: tmpl.categoryId },
                    ]);
                  }
                  select.value = "";
                }}
              >
                Add Template
              </Button>
            </div>

            <div className="space-y-3">
              {formData.terms.map((term: any, idx: number) => (
                <div
                  key={idx}
                  className="flex gap-3 items-start border p-3 rounded-md bg-white shadow-sm"
                >
                  <div className="flex-1">
                    <Textarea
                      className="min-h-[80px]"
                      value={term.content}
                      onChange={(e) => {
                        const newTerms = [...formData.terms];
                        newTerms[idx].content = e.target.value;
                        updateForm("terms", newTerms);
                      }}
                      placeholder="Enter legal clause here..."
                    />
                  </div>
                  <Button
                    variant="destructive"
                    size="icon"
                    className="mt-1"
                    onClick={() => {
                      const newTerms = [...formData.terms];
                      newTerms.splice(idx, 1);
                      updateForm("terms", newTerms);
                    }}
                  >
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              ))}

              {formData.terms.length === 0 && (
                <p className="text-center text-gray-500 py-4 border border-dashed rounded-md bg-gray-50">
                  No manual terms added. Backend defaults will apply.
                </p>
              )}

              <Button
                variant="outline"
                className="w-full border-dashed"
                onClick={() => {
                  updateForm("terms", [
                    ...formData.terms,
                    { content: "", categoryId: "" },
                  ]);
                }}
              >
                <Plus className="w-4 h-4 mr-2" /> Add Custom Term
              </Button>
            </div>
          </div>
        );
      case 4:
        return (
          <div className="space-y-4">
            <h3 className="text-xl font-semibold mb-4">Review Summary</h3>
            <div className="bg-blue-50 p-6 rounded-lg space-y-2">
              <p>
                <strong>Customer:</strong>{" "}
                {
                  customers.find((c: any) => c.id === formData.customerId)
                    ?.displayName
                }
              </p>
              <p>
                <strong>Service Type:</strong>{" "}
                {
                  serviceTypes.find((s: any) => s.id === formData.serviceTypeId)
                    ?.name
                }
              </p>
              <p>
                <strong>Project:</strong> {formData.projectTitle}
              </p>
              <p>
                <strong>Total Items:</strong> {formData.items.length}
              </p>

              <div className="pt-4 mt-4 border-t border-blue-200">
                <p className="text-sm text-gray-600">
                  Calculations will be finalized on the backend upon saving.
                </p>
              </div>
            </div>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold text-gray-800 tracking-tight">
          Edit Quotation
        </h1>
      </div>

      <div className="flex items-center justify-between mb-8">
        {STEPS.map((s, i) => (
          <div key={s} className="flex items-center text-sm font-medium">
            <div
              className={`flex items-center justify-center w-8 h-8 rounded-full border-2 ${
                step > i
                  ? "bg-blue-600 border-blue-600 text-white"
                  : step === i
                    ? "border-blue-600 text-blue-600"
                    : "border-gray-300 text-gray-400"
              }`}
            >
              {step > i ? <Check className="w-4 h-4" /> : i + 1}
            </div>
            <span
              className={`ml-2 hidden sm:block ${step >= i ? "text-gray-900" : "text-gray-400"}`}
            >
              {s}
            </span>
            {i < STEPS.length - 1 && (
              <div
                className={`w-12 h-1 mx-4 rounded ${step > i ? "bg-blue-600" : "bg-gray-200"}`}
              />
            )}
          </div>
        ))}
      </div>

      <Card className="shadow-lg border-none rounded-xl">
        <CardContent className="p-8 min-h-[400px]">
          {renderStepContent()}
        </CardContent>
        <div className="bg-gray-50 px-8 py-4 border-t flex justify-between rounded-b-xl">
          <Button variant="outline" onClick={handlePrev} disabled={step === 0}>
            <ChevronLeft className="w-4 h-4 mr-2" /> Previous
          </Button>

          {step < STEPS.length - 1 ? (
            <Button
              onClick={handleNext}
              disabled={
                (step === 0 && !formData.customerId) ||
                (step === 1 &&
                  (!formData.serviceTypeId || !formData.projectTitle))
              }
            >
              Next <ChevronRight className="w-4 h-4 ml-2" />
            </Button>
          ) : (
            <Button
              onClick={handleSaveDraft}
              disabled={isSaving}
              className="bg-green-600 hover:bg-green-700"
            >
              {isSaving ? "Saving..." : "Save Changes"}{" "}
              <Save className="w-4 h-4 ml-2" />
            </Button>
          )}
        </div>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState, use } from "react";
import { api } from "@/lib/axios";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { format } from "date-fns";
import {
  Download,
  Edit,
  ArrowLeft,
  Send,
  Play,
  CheckCircle,
  XCircle,
  History,
  Lock,
  FilePlus,
  Receipt,
  AlertTriangle,
  Plus,
  Trash2,
  Link2,
  Copy,
  Check,
} from "lucide-react";
import { useRouter } from "next/navigation";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import { useAuthStore } from "@/lib/store";
import { TrendingUp, AlertOctagon, Sparkles } from "lucide-react";

export default function QuotationDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const { user } = useAuthStore();
  const [quotation, setQuotation] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("details");
  const [isGenerating, setIsGenerating] = useState(false);
  const [showInvoiceModal, setShowInvoiceModal] = useState(false);
  const [invoiceType, setInvoiceType] = useState("FINAL");
  const [readiness, setReadiness] = useState<any>(null);
  const [diffData, setDiffData] = useState<any>(null);

  // Share Link State
  const [showShareLinkModal, setShowShareLinkModal] = useState(false);
  const [shareLinkUrl, setShareLinkUrl] = useState("");
  const [isGeneratingLink, setIsGeneratingLink] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  // Terms Management State
  const [showTermsModal, setShowTermsModal] = useState(false);
  const [editingTerms, setEditingTerms] = useState<any[]>([]);
  const [isSavingTerms, setIsSavingTerms] = useState(false);

  const [isSummarizing, setIsSummarizing] = useState(false);
  const [isEditingScope, setIsEditingScope] = useState(false);
  const [editScopeValue, setEditScopeValue] = useState("");

  const router = useRouter();

  async function fetchQuotation() {
    try {
      const [{ data: qData }, { data: rData }] = await Promise.all([
        api.get(`/quotations/${id}`),
        api.get(`/quotations/${id}/readiness`),
      ]);
      setQuotation(qData);
      setReadiness(rData);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (id) {
      fetchQuotation();
    }
  }, [id]);

  useEffect(() => {
    if (activeTab === "diff" && quotation?.parentQuotationId && !diffData) {
      api
        .get(`/quotations/${id}/compare/${quotation.parentQuotationId}`)
        .then((res) => setDiffData(res.data))
        .catch((err) => console.error(err));
    }
  }, [activeTab, quotation?.parentQuotationId, id, diffData]);


  async function handleAction(action: string, payload: any = {}) {
    try {
      if (action === "submit") {
        await api.post(`/quotations/${id}/submit-for-approval`);
        alert("Submitted for approval!");
      } else if (action === "approve") {
        await api.post(`/quotations/${id}/approve`, {
          comments: "Approved via UI",
        });
        alert("Quotation approved and locked!");
      } else if (action === "reject") {
        const reason = prompt("Enter rejection reason:");
        if (!reason) return;
        await api.post(`/quotations/${id}/reject`, { comments: reason });
        alert("Quotation rejected!");
      } else if (action === "revise") {
        const { data } = await api.post(`/quotations/${id}/create-revision`);
        alert(`Revision ${data.revisionNumber} created!`);
        router.push(`/dashboard/quotations/${data.id}`);
        return;
      } else if (action === "send") {
        const email = prompt(
          "Enter customer email:",
          quotation.customer?.email,
        );
        if (!email) return;
        const { data } = await api.post(`/quotations/${id}/send`, {
          recipientEmail: email,
        });
        alert(`Sent! Secure Link Token: ${data.token}`);
      }
      fetchQuotation();
    } catch (e) {
      console.error(e);
      alert("Action failed. Please check permissions and rules.");
    }
  };

  async function handleGenerateInvoice() {
    try {
      const { data } = await api.post(`/invoices/from-quotation/${id}`, {
        invoiceType,
      });
      alert(`Invoice Draft created! ID: ${data.id}`);
      setShowInvoiceModal(false);
      router.push(`/dashboard/invoices/${data.id}`);
    } catch (e) {
      console.error(e);
      alert("Failed to generate invoice.");
    }
  };

  async function handleAiSummarize() {
    setIsSummarizing(true);
    try {
      await api.post(`/quotations/${id}/ai-summarize`);
      alert("AI Summary generated successfully!");
      fetchQuotation();
    } catch (e) {
      console.error(e);
      alert("Failed to generate AI summary.");
    } finally {
      setIsSummarizing(false);
    }
  };

  async function handleSaveScope() {
    try {
      await api.patch(`/quotations/${id}`, { scopeSummary: editScopeValue });
      setIsEditingScope(false);
      fetchQuotation();
    } catch (e) {
      console.error(e);
      alert("Failed to save scope.");
    }
  };

  async function generatePdf() {
    setIsGenerating(true);
    try {
      const response = await api.post(`/quotations/${id}/generate-pdf`, {}, {
        responseType: "blob",
      });

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `${quotation.quotationNumber || "quotation"}.pdf`,
      );
      document.body.appendChild(link);
      link.click();
      link.parentNode?.removeChild(link);
    } catch (e) {
      console.error(e);
      alert("Failed to generate PDF");
    } finally {
      setIsGenerating(false);
    }
  };

  const openTermsModal = () => {
    setEditingTerms(quotation.terms ? [...quotation.terms] : []);
    setShowTermsModal(true);
  };

  async function handleSaveTerms() {
    setIsSavingTerms(true);
    try {
      const payload = editingTerms.map((t, idx) => ({
        categoryId: t.categoryId || "custom",
        content: t.content,
        sortOrder: idx,
      }));
      await api.post(`/quotations/${id}/terms`, payload);
      setShowTermsModal(false);
      fetchQuotation();
    } catch (e) {
      console.error(e);
      alert("Failed to save terms");
    } finally {
      setIsSavingTerms(false);
    }
  };

  if (loading) return <div className="p-8">Loading quotation details...</div>;
  if (!quotation) return <div className="p-8">Quotation not found</div>;

  return (
    <div className="space-y-6 max-w-7xl mx-auto">
      {showInvoiceModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center">
          <div className="bg-white rounded-xl p-6 w-full max-w-sm shadow-2xl">
            <h2 className="text-xl font-bold mb-4">Convert to Invoice</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">
                  Invoice Type
                </label>
                <select
                  className="w-full border rounded p-2"
                  value={invoiceType}
                  onChange={(e) => setInvoiceType(e.target.value)}
                >
                  <option value="ADVANCE_PAYMENT">Advance Payment</option>
                  <option value="MILESTONE">Milestone</option>
                  <option value="FINAL">Final</option>
                </select>
              </div>
              <div className="flex gap-2 justify-end mt-6">
                <Button
                  variant="outline"
                  onClick={() => setShowInvoiceModal(false)}
                >
                  Cancel
                </Button>
                <Button
                  className="bg-green-600 hover:bg-green-700"
                  onClick={handleGenerateInvoice}
                >
                  Create Draft
                </Button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Header Bar */}
      <div className="flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4 bg-white p-4 rounded-xl shadow-sm border border-gray-100">
        <div className="flex items-center gap-4">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => router.push("/dashboard/quotations")}
            className="shrink-0"
          >
            <ArrowLeft className="w-4 h-4 mr-2" /> Back
          </Button>
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-3">
              <span className="whitespace-nowrap">
                {quotation.quotationNumber}
              </span>
              {quotation.isLocked && (
                <Lock className="w-4 h-4 text-gray-400 shrink-0" />
              )}
              <Badge
                variant={
                  quotation.status === "APPROVED" ||
                  quotation.status === "SENT_TO_CUSTOMER"
                    ? "default"
                    : "secondary"
                }
                className="shrink-0"
              >
                {quotation.status.replace(/_/g, " ")}
              </Badge>
            </h1>
            <p className="text-sm text-gray-500">
              {quotation.customer?.displayName} • Revision{" "}
              {quotation.revisionNumber}
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2 xl:justify-end">
          <Button
            variant="outline"
            className="border-red-200 text-red-600 hover:bg-red-50"
            onClick={async () => {
              if (confirm("Are you sure you want to delete this quotation? This action cannot be undone.")) {
                try {
                  await api.delete(`/quotations/${id}`);
                  router.push("/dashboard/quotations");
                } catch (e) {
                  console.error(e);
                  alert("Failed to delete quotation.");
                }
              }
            }}
          >
            <Trash2 className="w-4 h-4 mr-2" /> Delete
          </Button>

          {!quotation.isLocked &&
            (quotation.status === "DRAFT" ||
              quotation.status === "REVISED") && (
              <>
                <Button variant="outline" onClick={() => router.push(`/dashboard/quotations/${id}/edit`)}>
                  <Edit className="w-4 h-4 mr-2" /> Edit
                </Button>
                <Button
                  variant="outline"
                  className="border-orange-200 text-orange-700 hover:bg-orange-50"
                  onClick={() => {
                    if (readiness && readiness.warnings.length > 0) {
                      if (
                        !confirm(
                          `Quotation has ${readiness.warnings.length} warnings. Are you sure you want to submit?\n\n- ` +
                            readiness.warnings.join("\n- "),
                        )
                      )
                        return;
                    }
                    handleAction("submit");
                  }}
                >
                  Submit for Approval
                </Button>
              </>
            )}

          {quotation.status === "PENDING_APPROVAL" && (
            <>
              <Button
                variant="outline"
                className="text-red-600 border-red-200"
                onClick={() => handleAction("reject")}
              >
                <XCircle className="w-4 h-4 mr-2" /> Reject
              </Button>
              <Button
                className="bg-green-600 hover:bg-green-700"
                onClick={() => handleAction("approve")}
              >
                <CheckCircle className="w-4 h-4 mr-2" /> Approve
              </Button>
            </>
          )}

          {quotation.isLocked && (
            <Button variant="outline" onClick={() => handleAction("revise")}>
              <FilePlus className="w-4 h-4 mr-2" /> Create Rev{" "}
              {quotation.revisionNumber + 1}
            </Button>
          )}

          <div className="flex bg-gray-100 p-1 rounded-md">
            <button
              className={`px-4 py-1.5 rounded-sm text-sm font-medium transition-colors ${activeTab === "details" ? "bg-white shadow text-gray-900" : "text-gray-500 hover:text-gray-900"}`}
              onClick={() => setActiveTab("details")}
            >
              Details
            </button>
            <button
              className={`px-4 py-1.5 rounded-sm text-sm font-medium transition-colors ${activeTab === "preview" ? "bg-white shadow text-gray-900" : "text-gray-500 hover:text-gray-900"}`}
              onClick={() => setActiveTab("preview")}
            >
              Live Preview
            </button>
            {quotation.parentQuotationId && (
              <button
                className={`px-4 py-1.5 rounded-sm text-sm font-medium transition-colors flex items-center ${activeTab === "diff" ? "bg-white shadow text-gray-900" : "text-gray-500 hover:text-gray-900"}`}
                onClick={() => setActiveTab("diff")}
              >
                <History className="w-4 h-4 mr-1" /> Compare Revisions
              </button>
            )}
          </div>

          <Button onClick={generatePdf} disabled={isGenerating}>
            <Download className="w-4 h-4 mr-2" /> Generate PDF
          </Button>

          <Button
            variant="outline"
            className="border-teal-200 text-teal-700 hover:bg-teal-50"
            disabled={isGeneratingLink}
            onClick={async () => {
              setIsGeneratingLink(true);
              try {
                const { data } = await api.post(`/quotations/${id}/generate-share-link`);
                setShareLinkUrl(data.portalLink);
                setLinkCopied(false);
                setShowShareLinkModal(true);
              } catch (e) {
                console.error(e);
                alert("Failed to generate share link.");
              } finally {
                setIsGeneratingLink(false);
              }
            }}
          >
            <Link2 className="w-4 h-4 mr-2" /> {isGeneratingLink ? "Generating..." : "Share Link"}
          </Button>

          {(quotation.status === "APPROVED" ||
            quotation.status === "SENT_TO_CUSTOMER" ||
            quotation.status === "ACCEPTED") && (
              <Button
                className="bg-purple-600 hover:bg-purple-700"
                onClick={() => setShowInvoiceModal(true)}
              >
                <Receipt className="w-4 h-4 mr-2" /> Convert to Invoice
              </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-4 gap-6">
        <div className="xl:col-span-3">
          {readiness &&
            readiness.warnings.length > 0 &&
            !quotation.isLocked && (
              <div className="mb-6 p-4 bg-yellow-50 border border-yellow-200 rounded-lg text-yellow-800">
                <h4 className="font-bold flex items-center mb-2">
                  <AlertTriangle className="w-4 h-4 mr-2" /> Quotation Readiness
                  Warnings
                </h4>
                <ul className="list-disc pl-5 space-y-1 text-sm">
                  {readiness.warnings.map((w: string, i: number) => (
                    <li key={i}>{w}</li>
                  ))}
                </ul>
                <div className="mt-3 text-xs font-semibold">
                  Readiness Score: {readiness.score.toFixed(0)}%
                </div>
              </div>
            )}

          {activeTab === "details" ? (
            <div className="space-y-6">
              <Card className="border-none shadow-sm">
                <CardContent className="p-6">
                  <div className="flex justify-between items-start mb-4">
                    <h3 className="text-lg font-bold">Project Information</h3>
                    {!quotation.isLocked && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={handleAiSummarize}
                        disabled={
                          isSummarizing || quotation.items?.length === 0
                        }
                      >
                        <Sparkles className="w-4 h-4 mr-2 text-purple-600" />
                        {isSummarizing ? "Generating..." : "AI Summarize Scope"}
                      </Button>
                    )}
                  </div>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm mb-6">
                    <div>
                      <p className="text-gray-500">Project Title</p>
                      <p className="font-medium">
                        {quotation.projectTitle || "N/A"}
                      </p>
                    </div>
                    <div>
                      <p className="text-gray-500">Location</p>
                      <p className="font-medium">
                        {quotation.projectLocation || "N/A"}
                      </p>
                    </div>
                    <div>
                      <p className="text-gray-500">Service Type</p>
                      <p className="font-medium">
                        {quotation.serviceType?.name}
                      </p>
                    </div>
                    <div>
                      <p className="text-gray-500">Valid Until</p>
                      <p className="font-medium">
                        {quotation.validUntil
                          ? format(
                              new Date(quotation.validUntil),
                              "MMM d, yyyy",
                            )
                          : "N/A"}
                      </p>
                    </div>
                  </div>
                  {isEditingScope ? (
                    <div>
                      <p className="text-gray-500 text-sm mb-1">
                        Edit Scope Summary
                      </p>
                      <Textarea
                        className="min-h-[120px] text-sm mb-2"
                        value={editScopeValue}
                        onChange={(e) => setEditScopeValue(e.target.value)}
                        placeholder="Briefly describe the overall scope of this project..."
                      />
                      <div className="flex gap-2">
                        <Button size="sm" onClick={handleSaveScope}>
                          Save Scope
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setIsEditingScope(false)}
                        >
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div>
