    try {
      const { data: quotation } = await api.post("/quotations", {
        companyId: user?.companyId,
        customerId: formData.customerId,
        serviceTypeId: formData.serviceTypeId,
        projectTitle: formData.projectTitle,
        projectLocation: formData.projectLocation,
        scopeSummary: formData.scopeSummary,
        currency: formData.currency,
      });

      if (formData.items.length > 0) {
        const itemsPayload = await Promise.all(formData.items.map(async (i: any) => {
          const { brand, image, taxRate, productId, serviceItemId, ...rest } = i;
          const payload: any = { ...rest, taxRate: taxRate || 0 };

          if (productId) {
            payload.productId = productId;
            // If product exists, omit image from payload to drastically reduce size. PDF picks it up.
          } else if (image) {
            payload.image = await compressImage(image, 250);
          }

          if (serviceItemId) payload.serviceItemId = serviceItemId;
          return payload;
        }));
        await api.post(`/quotations/${quotation.id}/items`, itemsPayload);
      }

      if (formData.terms.length > 0) {
        const payload = formData.terms.map((t: any, idx: number) => {
          const res: any = { content: t.content, sortOrder: idx };
          if (t.categoryId) res.categoryId = t.categoryId;
          return res;
        });
        await api.post(`/quotations/${quotation.id}/terms`, payload);
      }

      router.push(`/dashboard/quotations/${quotation.id}`);
    } catch (e) {
      console.error(e);
      alert("Failed to save quotation");
    } finally {
      setIsSaving(false);
    }
