"use client";

import { useSearchParams } from "next/navigation";
import { useEffect, useState, Suspense } from "react";
import {
  BuildingAutomationCoverPage,
  BuildingAutomationAboutPage,
  BuildingAutomationScopePage,
  BuildingAutomationQuotationPage,
  BuildingAutomationFinalPage,
} from "@qmanager/pdf-templates";

const FontLoader = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');
    * { box-sizing: border-box; }
    body { margin: 0; padding: 0; background: #e5e7eb; }
    @media print { body { background: white; } }
  `}</style>
);

function BuildingAutomationRenderPageInner() {
  const searchParams = useSearchParams();
  const quotationId = searchParams.get("quotationId");
  const docId = searchParams.get("docId") || quotationId || "UNKNOWN";

  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      if (!quotationId) {
        setData(getSampleData(docId));
        setLoading(false);
        return;
      }
      try {
        const res = await fetch(
          `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"}/internal/quotations/${quotationId}`,
          { headers: { "x-internal-pdf-render": "1" } },
        );
        setData(
          res.ok
            ? transformQuotation(await res.json(), docId)
            : getSampleData(docId),
        );
      } catch {
        setData(getSampleData(docId));
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [quotationId, docId]);

  if (loading) {
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          height: "100vh",
          fontFamily: "Inter, sans-serif",
          color: "#64748b",
        }}
      >
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: "32px", marginBottom: "12px" }}>🏗️</div>
          <div>Generating Building Automation Proposal...</div>
        </div>
      </div>
    );
  }

  if (!data) return null;

  const verifyUrl = `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}`;

  return (
    <>
      <FontLoader />
      <div className="pdf-container print:bg-white bg-gray-200 flex flex-col items-center py-10 print:py-0 print:block">
        <BuildingAutomationCoverPage
          projectName={data.projectName}
          customerName={data.customerName}
          customerCompany={data.customerCompany}
          proposalDate={data.proposalDate}
          proposalReference={data.proposalReference}
          revisionNumber={data.revisionNumber}
          projectLocation={data.projectLocation}
        />
        <BuildingAutomationAboutPage />
        {!data.scopeSummary && <BuildingAutomationScopePage items={data.items} />}
        <BuildingAutomationQuotationPage
          items={data.items}
          subtotal={data.subtotal}
          discount={data.discount}
          tax={data.tax}
          grandTotal={data.grandTotal}
          currency={data.currency}
          scopeSummary={data.scopeSummary}
        />
        <BuildingAutomationFinalPage
          terms={data.terms}
          paymentTerms={data.paymentTerms}
          validityPeriod={data.validityPeriod}
          deliveryTimeline={data.deliveryTimeline}
          customerName={data.customerName}
          qrVerificationUrl={verifyUrl}
          proposalReference={data.proposalReference}
          proposalDate={data.proposalDate}
        />
      </div>
    </>
  );
}

export default function BuildingAutomationRenderPage() {
  return (
    <Suspense
      fallback={
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            height: "100vh",
            fontFamily: "Inter, sans-serif",
            color: "#64748b",
          }}
        >
          <div style={{ textAlign: "center" }}>
            <div style={{ fontSize: "32px", marginBottom: "12px" }}>🏗️</div>
            <div>Loading...</div>
          </div>
        </div>
      }
    >
      <BuildingAutomationRenderPageInner />
    </Suspense>
  );
}

function transformQuotation(q: any, docId: string) {
  const terms = q.terms || [];
  const find = (kw: string) =>
    terms.find((t: any) => t.category?.name?.toLowerCase().includes(kw))
      ?.content;
  return {
    projectName: q.projectTitle || "Building Automation Project",
    customerName: q.customer?.displayName || "Valued Customer",
    customerCompany: q.customer?.company || "",
    proposalDate: q.issueDate
      ? new Date(q.issueDate).toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        })
      : new Date().toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        }),
    proposalReference: q.quotationNumber || docId,
    revisionNumber: String(q.revisionNumber ?? 0),
    projectLocation: q.projectLocation || "",
    items: (() => {
      let counter = 0;
      return (q.items || []).map((i: any) => {
        let serialNumber = "";
        if (i.itemType !== "SECTION_HEADING" && !i.isOptional) {
          counter++;
          serialNumber = String(counter).padStart(2, "0");
        }
        return {
          ...i,
          brand: i.product?.brand || "",
          image: i.image || i.product?.productImage || "",
          serialNumber,
        };
      });
    })(),
    subtotal: q.subtotal || 0,
    discount: q.discountAmount || 0,
    tax: q.taxAmount || 0,
    grandTotal: q.grandTotal || 0,
    currency: q.currency || "KWD",
    scopeSummary: q.scopeSummary || "",
    terms: q.terms || [],
    paymentTerms: find("payment") || "",
    validityPeriod: find("validity") || "",
    deliveryTimeline: find("delivery") || find("timeline") || "",
  };
}

