import { useSearchParams } from "next/navigation";
import { useEffect, useState, Suspense } from "react";
import {
  SoftwareDevCoverPage,
  SoftwareDevAboutPage,
  SoftwareDevCommercialFlow,
} from "@qmanager/pdf-templates";

const FontLoader = () => (
  <style>{`
    @import url('https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600;700;800;900&family=Inter:wght@300;400;500;600;700&display=swap');
    * { box-sizing: border-box; }
    body { margin: 0; padding: 0; background: #e5e7eb; }
    @media print { body { background: white; } }
  `}</style>
);

function SoftwareDevRenderPageInner() {
  const searchParams = useSearchParams();
  const quotationId = searchParams.get("quotationId");
  const docId = searchParams.get("docId") || quotationId || "UNKNOWN";
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      if (!quotationId) {
        setData(getSampleData(docId));
        setLoading(false);
        return;
      }
      try {
        const res = await fetch(
          `${process.env.NEXT_PUBLIC_API_URL || "http://localhost:3001"}/internal/quotations/${quotationId}`,
          { headers: { "x-internal-pdf-render": "1" } },
        );
        setData(
          res.ok
            ? transformQuotation(await res.json(), docId)
            : getSampleData(docId),
        );
      } catch {
        setData(getSampleData(docId));
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [quotationId, docId]);

  if (loading)
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          height: "100vh",
          fontFamily: "Inter, sans-serif",
          color: "#64748b",
        }}
      >
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: "32px", marginBottom: "12px" }}>💻</div>
          <div>Generating Software Proposal...</div>
        </div>
      </div>
    );
  if (!data) return null;

  const verifyUrl = `${process.env.NEXT_PUBLIC_APP_URL || "http://localhost:3000"}`;

  return (
    <>
      <FontLoader />
      <div className="pdf-container print:bg-white bg-gray-200 flex flex-col items-center py-10 print:py-0 print:block">
        <SoftwareDevCoverPage
          projectName={data.projectName}
          customerName={data.customerName}
          customerCompany={data.customerCompany}
          proposalDate={data.proposalDate}
          proposalReference={data.proposalReference}
          revisionNumber={data.revisionNumber}
          projectLocation={data.projectLocation}
        />
        <SoftwareDevAboutPage />
        <SoftwareDevCommercialFlow
          items={data.items}
          subtotal={data.subtotal}
          discount={data.discount}
          tax={data.tax}
          grandTotal={data.grandTotal}
          currency={data.currency}
          scopeSummary={data.scopeSummary}
          terms={data.terms}
          paymentTerms={data.paymentTerms}
          validityPeriod={data.validityPeriod}
          deliveryTimeline={data.deliveryTimeline}
          customerName={data.customerName}
          qrVerificationUrl={verifyUrl}
          proposalReference={data.proposalReference}
          proposalDate={data.proposalDate}
        />
      </div>
    </>
  );
}

