function transformQuotation(q: any, docId: string) {
  const terms = q.terms || [];
  const find = (kw: string) =>
    terms.find((t: any) => t.category?.name?.toLowerCase().includes(kw))
      ?.content;
  return {
    projectName: q.projectTitle || "Software Development Project",
    customerName: q.customer?.displayName || "Valued Customer",
    customerCompany: q.customer?.company || "",
    proposalDate: q.issueDate
      ? new Date(q.issueDate).toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        })
      : new Date().toLocaleDateString("en-GB", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        }),
    proposalReference: q.quotationNumber || docId,
    revisionNumber: String(q.revisionNumber ?? 0),
    projectLocation: q.projectLocation || "",
    items: (() => {
      let counter = 0;
      return (q.items || []).map((i: any) => {
        let serialNumber = "";
        if (i.itemType !== "SECTION_HEADING" && !i.isOptional) {
          counter++;
          serialNumber = String(counter).padStart(2, "0");
        }
        return {
          ...i,
          brand: i.product?.brand || "",
          image: i.image || i.product?.productImage || "",
          serialNumber,
        };
      });
    })(),
    subtotal: q.subtotal || 0,
    discount: q.discountAmount || 0,
    tax: q.taxAmount || 0,
    grandTotal: q.grandTotal || 0,
    currency: q.currency || "KWD",
    scopeSummary: q.scopeSummary || "",
    terms: q.terms || [],
    paymentTerms: find("payment") || "",
    validityPeriod: find("validity") || "",
    deliveryTimeline: find("delivery") || find("timeline") || "",
  };
}

